import{_ as d}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o,X as a}from"./chunks/vendor-vueuse.XPft87tp.js";const m=JSON.parse('{"title":"MySQL 数据类型","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/mysql-data-types.md","filePath":"mysql/mysql-data-types.md","lastUpdated":1786990830000}'),c={name:"mysql/mysql-data-types.md"};function r(h,t,l,s,p,T){return o(),e("div",null,t[0]||(t[0]=[a('<h1 id="mysql-数据类型" tabindex="-1">MySQL 数据类型 <a class="header-anchor" href="#mysql-数据类型" aria-label="Permalink to &quot;MySQL 数据类型&quot;">​</a></h1><h3 id="数值类型" tabindex="-1">数值类型 <a class="header-anchor" href="#数值类型" aria-label="Permalink to &quot;数值类型&quot;">​</a></h3><p>整数按存储宽度分档：TINYINT、SMALLINT、MEDIUMINT、INT、BIGINT，大约占用 1、2、3、4、8 字节。主键、用户 ID 用 <code>BIGINT</code> 更稳妥，避免业务增长后改列类型。</p><p><code>INT(10)</code> 里的 <code>10</code> 是显示宽度，不改变取值范围。只有配合 <code>ZEROFILL</code> 时才会在展示时左侧补零。MySQL 8.0.17 起整数显示宽度已废弃，不要再用它表达「这个数字有几位」。</p><p>金额、汇率、精确小数用 <code>DECIMAL(M,D)</code>。<code>FLOAT</code> / <code>DOUBLE</code> 是二进制浮点，<code>0.1 + 0.2</code> 这类误差会直接进账本。<code>FLOAT(5,2)</code> 这种非标准声明也不建议，精度在 DECIMAL 上写清楚即可。</p><h3 id="字符串与字符集" tabindex="-1">字符串与字符集 <a class="header-anchor" href="#字符串与字符集" aria-label="Permalink to &quot;字符串与字符集&quot;">​</a></h3><p><code>CHAR(N)</code> 定长，短且长度稳定的码表适合用，例如国家码、固定宽度状态码。不足的部分会补空格，检索时再去掉尾部空格。</p><p><code>VARCHAR(N)</code> 变长，多数字段的默认选择。<code>N</code> 是字符数，实际字节还受字符集影响：<code>utf8mb4</code> 最坏按 4 字节计，行长度上限会把 <code>VARCHAR</code> 的最大长度往下压。</p><p>字符集用 <code>utf8mb4</code>。MySQL 里名叫 <code>utf8</code> 的其实是 <code>utf8mb3</code>，三字节 UTF-8 存不下 emoji 和部分生僻字，写入会报错或截断。</p><p><code>TEXT</code> / <code>BLOB</code> 适合真正的大字段。它们更容易让查询走临时表，也很难被覆盖索引带上。能拆到扩展表就拆，列表查询不要 <code>SELECT *</code> 把正文一并带出。</p><h3 id="日期时间" tabindex="-1">日期时间 <a class="header-anchor" href="#日期时间" aria-label="Permalink to &quot;日期时间&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>大致范围</th><th>存储</th><th>时区</th></tr></thead><tbody><tr><td>DATETIME</td><td>1000-01-01 ~ 9999-12-31</td><td>5~8 字节（版本有关）</td><td>存什么就是什么</td></tr><tr><td>TIMESTAMP</td><td>1970 ~ 2038（32 位时代）</td><td>旧实现 4 字节</td><td>按会话时区转换</td></tr></tbody></table><p>业务上的「下单时间、生日、活动开始时间」更稳妥用 <code>DATETIME</code>：看到的值和写入值一致，也不用提前处理 2038 年问题。</p><p><code>TIMESTAMP</code> 会按时区转换，同一条记录在 <code>+08:00</code> 和 <code>UTC</code> 会话里读出来不一样。多个机房、要「跟着用户时区显示」时它有用；只是想存一个绝对时间，时区转换反而是坑。</p><h3 id="常见选型" tabindex="-1">常见选型 <a class="header-anchor" href="#常见选型" aria-label="Permalink to &quot;常见选型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>用途</th><th>建议</th></tr></thead><tbody><tr><td>主键 / 用户 ID</td><td><code>BIGINT</code></td></tr><tr><td>金额</td><td><code>DECIMAL</code></td></tr><tr><td>短文本</td><td><code>VARCHAR</code> + <code>utf8mb4</code></td></tr><tr><td>长文本</td><td><code>TEXT</code>，必要时垂直拆表</td></tr><tr><td>业务时间</td><td><code>DATETIME</code></td></tr><tr><td>半结构化</td><td><code>JSON</code></td></tr></tbody></table><p>列类型一旦写进聚簇索引和所有二级索引，后面改类型就是重建表。能在建表时选对，比上线后再 <code>ALTER</code> 便宜得多。</p>',17)]))}const I=d(c,[["render",r]]);export{m as __pageData,I as default};
